'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), enc=encodeURIComponent;
const names={asset_import:'资产导入',preprocess:'预处理',initialization:'Model / State 初始化',control:'Control',collision:'Collision detection',solver_step:'solver.step()',output:'导出与渲染'};
const kindNames={api:'API 模块',concept:'概念',topic:'跨阶段主题',stage:'流程阶段',recipe:'调用配方',parameter:'参数',model_input:'模型输入',claim:'源码结论',diagnostic:'诊断方案',mapping:'论文与代码映射',paper:'论文',source_symbol:'源码符号',lab_experiment:'实测实验',experiment:'CPU 探针',document:'知识文档',solver:'Solver'};
let catalog,main=$('#main'),navigation=0;
async function api(path){const response=await fetch(path);const data=await response.json();if(!response.ok)throw Error(data.message||data.error||response.status);if(data.build_id&&catalog&&data.build_id!==catalog.build_id){catalog=await (await fetch('/api/catalog')).json();$('#build-id').textContent=catalog.build_id.slice(0,12);}return data;}
function head(title,lead='',scope='NEWTON 1.7.0'){return `<div class="page-head"><div><div class="eyebrow">${esc(scope)}</div><h1>${esc(title)}</h1><p class="lead">${esc(lead)}</p></div><div class="head-note">SOURCE ${catalog.commit.slice(0,12)}<br>BUILD ${catalog.build_id.slice(0,12)}</div></div>`;}
function badge(text,style=''){return `<span class="badge ${style}">${esc(text)}</span>`;}
function recordLink(id,label){return `<a href="#/record/${enc(id)}">${esc(label||id)}</a>`;}
function docLink(path,label){return `<a href="#/document/${enc(path).replaceAll('%2F','/')}">${esc(label||path)}</a>`;}
function entryCards(entries){return `<div class="grid-3">${entries.map(e=>`<article class="card"><div class="kicker">${esc(kindNames[e.family]||e.family)} · ${esc(e.target_depth)}</div><h3>${recordLink(e.id,e.title)}</h3><p>${esc(e.observed_state)}${e.family==='api'?` · ${e.public_exports.length} 个模块公开导出`:''}</p><a class="card-link" href="#/record/${enc(e.id)}">知识入口与固定来源 →</a></article>`).join('')}</div>`;}
function stats(items){return `<div class="stats">${items.map(([n,label,note])=>`<div class="stat"><div class="value">${esc(n)}</div><span>${esc(label)}</span><small>${esc(note||'')}</small></div>`).join('')}</div>`;}
function flow(){const order=['asset_import','preprocess','initialization','solver_step','output'];return `<div class="flow-row">${order.map((s,i)=>`${i?'<span>→</span>':''}<a href="#/workflow/${s}">${esc(s==='solver_step'?'求解循环':names[s])}</a>`).join('')}</div><div class="flow-row"><span>求解循环：</span>${['control','collision','solver_step'].map((s,i)=>`${i?'<span>→</span>':''}<a href="#/workflow/${s}">${esc(names[s])}</a>`).join('')}</div>`;}
function solverCards(){return `<div class="grid-3">${Object.entries(catalog.solvers).map(([id,s])=>`<article class="card" data-solver-card="${id}"><h3><a href="#/solvers/${id}">${esc(s.name)}</a></h3><div class="badges">${badge(s.coverage_level==='deep'?'深入知识库':'源码索引')}${badge(s.experiments.length+' 组实测',s.experiments.length?'measured':'neutral')}</div><p>${s.coverage_level==='deep'?`${s.parameters.length} 条构造 / 配置 / reset 字段，${s.model_inputs.length} 条模型输入。`:'已定位正式公开类与源码；参数详解、诊断和实测尚未建设。'}</p><a class="card-link" href="#/solvers/${id}">打开 ${esc(s.name)} 专区 →</a></article>`).join('')}</div>`;}
function solverNavigation(solver,tab='overview'){
 const s=catalog.solvers[solver];if(!s&&solver!=='shared')throw Error('未知 solver。');
 return `<div class="solver-tabs">${[['overview','总览'],['theory','原理与知识'],['parameters','参数与配置'],['inputs','模型输入'],['diagnostics','现象诊断'],['experiments','参数实验室'],['papers','论文与源码']].map(([k,l])=>`<a href="#/solvers/${solver}${k==='overview'?'':'/'+k}" class="${tab===k?'active':''}">${l}</a>`).join('')}</div>`;
}
function context(solver){const element=$('#solver-context');if(!solver||solver==='shared'){element.innerHTML='';return;}element.innerHTML=`<div class="solver-label">当前 SOLVER</div><select id="solver-select" class="solver-select" aria-label="选择 solver">${Object.entries(catalog.solvers).map(([id,s])=>`<option value="${id}" ${id===solver?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`;$('#solver-select').onchange=e=>{const route=location.hash.split('?')[0].split('/');const tab=['parameters','inputs','diagnostics','experiments','papers','theory'].includes(route[3])?'/'+route[3]:'';location.hash='#/solvers/'+e.target.value+tab;};}
function home(){main.innerHTML=head('Newton 仿真知识工作台','先了解对象、流程和模块，再进入各 solver 的原理、源码、参数与实验。所有内容固定于 Newton 1.7.0。')+stats([[12,'公开 API 模块'],[14,'核心概念'],[8,'具体 solver'],[catalog.total_counts.records,'可检索记录']])+`<div class="section-head"><h2>统一对象模型</h2></div><div class="grid-3">${[['ModelBuilder → Model','构建资产、拓扑、材料和约束；finalize 后由 Model 持有仿真所需数据。','symbol:newton.ModelBuilder'],['State / Control','State 保存动态状态；Control 提供关节目标、驱动力和执行器输入。','symbol:newton.Control'],['Contacts / Solver','碰撞提供接触几何，solver 推进状态；具体的碰撞与观测生命周期由后端决定。','module:solvers']].map(([t,p,id])=>`<article class="card"><h3>${recordLink(id,t)}</h3><p>${esc(p)}</p></article>`).join('')}</div><div class="section-head"><h2>经典求解流程</h2><a href="#/workflow">展开各阶段 →</a></div>`+flow()+`<div class="section-head"><h2>Solver 中心</h2><a href="#/solvers">查看覆盖状态 →</a></div>`+solverCards()+`<div class="notice">覆盖等级分别记录“已索引、已解释、任务验证、实验验证”。索引入口和待建设页面不等同于完成解释或实测。</div>`;}
function stageSummary(stage,nested=false){const e=catalog.registry.entries.find(e=>e.id==='stage:'+stage);return `<details class="${nested?'loop-stage':'flow-stage'}"><summary>${esc(names[stage])}<span class="mini-status">${esc(e.observed_state)}</span></summary><p>${esc(e.summary)}</p><p>${esc((e.description||'').replace(/##[^\n]*/g,'').slice(0,420))}</p><div class="actions">${recordLink(e.id,'完整阶段知识库 →')}${e.official_url?`<a href="${esc(e.official_url)}" target="_blank" rel="noopener">Newton 官方文档 ↗</a>`:''}</div>${entryCards(allEntries().filter(v=>v.stages.includes(stage)&&['api','topic','recipe'].includes(v.family)))}</details>`;}
function workflow(){main.innerHTML=head('仿真流程','展开阶段查看作用、输入输出、排查问题与官方文档；求解循环包含控制、碰撞和步进。')+flow()+['asset_import','preprocess','initialization'].map(s=>stageSummary(s)).join('')+`<details class="flow-stage" open><summary>求解循环<span class="mini-status">control → collision detection → solver.step()</span></summary><p>按选定后端的实际路径组织碰撞、观测和状态交换；原生检测可能发生在 step 内。</p><div class="flow-nested">${['control','collision','solver_step'].map(s=>stageSummary(s,true)).join('')}</div></details>`+stageSummary('output');}
function developerOverview(){main.innerHTML+=`<div class="section-head"><h2>编写与验证 Newton 代码</h2><a href="#/development">开发与测试 →</a></div><div class="grid-2"><article class="card"><h3>${recordLink('topic:development-testing','Coding style')}</h3><p>通过公开 newton.* 路径导入，以 __all__ 确定 API；保留类型、单位、docstring 与 Warp 数组布局，明确 experimental 和弃用边界。</p></article><article class="card"><h3>${recordLink('topic:development-testing','Newton test')}</h3><p>上游入口为 python -m newton.tests；示例通过 test_post_step / test_final 验证。上游测试、本库结构检查、MCP 与物理实验各自记录执行证据。</p></article></div>`;}
function recordBreadcrumb(r){const labels={parameter:'参数与配置',model_input:'模型输入',diagnostic:'现象诊断',lab_experiment:'参数实验室',paper:'论文与源码'};const label=labels[r.record_type]||'知识库';if(r.owner_solver){$('#crumb').innerHTML=`<a href="#/solvers">Solver 中心</a> / <a href="#/solvers/${r.owner_solver}">${esc(catalog.solvers[r.owner_solver].name)}</a> / ${esc(label)} / ${esc(r.title)}`;}else if(r.domain==='workflow'||r.stages.includes('collision')){$('#crumb').innerHTML=`<a href="#/workflow">仿真流程</a> / ${esc(r.stages.includes('collision')?'碰撞检测':kindNames[r.record_type]||'公共知识')} / ${esc(r.title)}`;}else $('#crumb').innerHTML=`<a href="#/modules">公共知识</a> / ${esc(r.title)}`;}

function allEntries(){return [...catalog.registry.entries,...(catalog.extensions||[])];}
function modules(){main.innerHTML=head('模块与跨阶段主题','覆盖公开 API、核心概念及跨模块关系；模块导出的源码符号可直接检索。')+['api','concept','topic','recipe'].map(f=>`<div class="section-head"><h2>${esc({api:'公开 API 模块',concept:'核心概念',topic:'跨阶段主题',recipe:'执行配方 · 首版与任务深化'}[f])}</h2></div>`+entryCards(allEntries().filter(e=>e.family===f))).join('');}
function defaultDisplay(p){return p.required?'必填':p.declared_default_expression??p.resolved_default??p.units??'按 Model 解析';}
function table(rows,solver,model=false){main.innerHTML+=`<div class="filters"><input id="parameter-filter" type="search" placeholder="按名称、作用或所属层筛选…" aria-label="筛选当前 solver 参数"><span id="parameter-count" class="count"></span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>名称 / 作用</th><th>所属层</th><th>声明默认 / 单位</th></tr></thead><tbody id="parameter-rows"></tbody></table></div>`;
 const update=()=>{const query=$('#parameter-filter').value.toLowerCase();const found=rows.filter(r=>JSON.stringify([r.name||r.field,r.summary_zh||r.description_zh,r.layer||r.category]).toLowerCase().includes(query));$('#parameter-count').textContent=found.length+' / '+rows.length;$('#parameter-rows').innerHTML=found.map(r=>`<tr><td>${recordLink(r.id,r.name||r.field)}<p class="summary">${esc(r.summary_zh||r.description_zh)}</p></td><td>${esc(r.layer||r.category||'Model')}</td><td><code>${esc(model?r.units:defaultDisplay(r))}</code></td></tr>`).join('');};$('#parameter-filter').oninput=update;update();}
function solverPage(id,tab,q){const s=catalog.solvers[id];if(!s){if(id==='shared'){main.innerHTML=head('公共流程参数','属于碰撞管线或调用方仿真循环。')+`<div class="detail-panel">${recordLink('pipeline:enable_rigid_soft_full_surface_contact','Full surface contact')}<br>${recordLink('process:substeps','Substeps')}</div>`;return;}throw Error('未知 solver。');}
 main.innerHTML=head(s.name+' · '+({overview:'知识库',theory:'原理与知识',parameters:'参数与配置',inputs:'模型输入',diagnostics:'现象诊断',experiments:'参数实验室',papers:'论文与源码'}[tab]||tab),'所有条目、统计和实验均使用当前 solver 的数据。','NEWTON 1.7.0 / '+s.name)+solverNavigation(id,tab);
 if(s.coverage_level==='indexed'){main.innerHTML+=`<div class="notice warm">${esc(s.name)} 当前达到源码索引级。参数详解、诊断和 A/B 尚未建设；实验空缺不代表后端不支持该功能。</div>`;if(!['overview','theory','papers'].includes(tab))return;}
 if(tab==='parameters'||tab==='inputs'){table(tab==='parameters'?s.parameters:s.model_inputs,id,tab==='inputs');if(id==='vbd'&&tab==='parameters')main.innerHTML+=`<div class="notice">另外两个常用设置属于公共流程：${recordLink('pipeline:enable_rigid_soft_full_surface_contact','full surface contact')} · ${recordLink('process:substeps','substeps')}。</div>`;return;}
 if(tab==='experiments'){if(!s.experiments.length){main.innerHTML+=`<div class="empty" data-empty-experiments="${id}">暂无 ${esc(s.name)} 保存的 A/B 实测。可查看本 solver 的诊断方案与固定源码。</div>`;return;}
  const chosen=s.experiments.find(e=>e.id===q.get('case'));const mode=q.get('view')==='2d'?'2d':'3d';const caseQuery=chosen?'&case='+enc(chosen.id):'';
  const viewer=chosen?.artifact_root?chosen.viewer_url+(chosen.viewer_url.includes('?')?'&':'?')+'embed=1':id==='vbd'?`/files/experiments/vbd_parameter_lab/${mode==='3d'?'index-3d':'index'}.html?embed=1${caseQuery}`:`/files/experiments/solver_parameter_lab/index.html?embed=1&solver=${enc(id)}${caseQuery}`;
  main.innerHTML+=`<div class="lab-toolbar"><select id="experiment-select" aria-label="选择参数实验"><option value="">所有 ${s.experiments.length} 组实验</option>${s.experiments.map(e=>`<option value="${e.id}" ${chosen?.id===e.id?'selected':''}>${esc(e.parameter+' · '+e.title)}</option>`).join('')}</select>${id==='vbd'?`<div class="segmented"><a class="${mode==='3d'?'active':''}" href="#/solvers/${id}/experiments?view=3d${caseQuery}">三维</a><a class="${mode==='2d'?'active':''}" href="#/solvers/${id}/experiments?view=2d${caseQuery}">X–Z</a></div>`:'<span>实体轮廓三维回放 · 旋转 / 缩放 / 多视角</span>'}${chosen?recordLink(chosen.record_id,'指标与证据'):''}</div><iframe class="lab-frame" title="${esc(s.name)} 实测实验" src="${viewer}"></iframe>`;
  if(!chosen){const roots=[...new Set(s.experiments.map(e=>e.artifact_root).filter(Boolean))];for(const root of roots){const label=root.includes("mujoco_joint_contact_lab")?"关节、摩擦与接触实验":"机制与工作流实验";main.innerHTML+=`<h2>${label}</h2><iframe class="lab-frame" title="${esc(s.name)} ${label}" src="/files/${esc(root)}index.html?embed=1"></iframe>`;}}
  $('#experiment-select').onchange=e=>{location.hash=`#/solvers/${id}/experiments?view=${mode}`+(e.target.value?'&case='+enc(e.target.value):'');};return;}
 if(tab==='diagnostics'){main.innerHTML+=`<div class="notice warm">诊断方案为 proposed。保存的实验另行标注；方案本身不构成已验证物理结论。</div>`+s.diagnostics.map(d=>`<article class="detail-panel"><h2>${recordLink(d.id,d.symptom)}</h2><ol>${d.plan.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><p>${esc(d.caution)}</p></article>`).join('');return;}
 if(tab==='papers'){main.innerHTML+=`<div class="grid-3">${s.papers.map(p=>`<article class="card"><h3>${recordLink(p.id,p.title)}</h3><p>${esc(p.role)}</p><div class="actions"><a class="btn" href="/files/${esc(p.local_path)}" target="_blank" rel="noopener">本地 PDF · ${p.pages} 页 ↗</a>${recordLink(p.id,'对应关系')}</div></article>`).join('')}</div>`;}
 if(tab==='overview'){const failed=s.experiments.filter(e=>e.physical_acceptance&&e.physical_acceptance!=='passed').length;main.innerHTML+=stats([[s.parameters.length,'构造 / 配置 / reset 字段'],[s.model_inputs.length,'模型输入'],[s.experiments.length,'保存实验 / 对照'],[s.papers.length,'论文']])+`<div class="notice">${id==='kamino'?'Kamino 在固定版本中标为 BETA 1 / experimental。':''}${s.experiments.length?'实测结论仅覆盖各保存场景、参数值与运行条件。':'尚无该 solver 的参数 A/B 实测。'}${failed?`其中 ${failed} 组未通过预设物理门槛，保留为负结果。`:''}</div>`;}
 main.innerHTML+=`<div class="section-head"><h2>知识与复现文档</h2></div><div class="grid-3">${catalog.documents.filter(d=>d.solver===id).map(d=>`<article class="card"><h3>${docLink(d.path,d.title)}</h3><p>${esc(d.path)}</p></article>`).join('')}</div><div class="source-summary">${recordLink(s.registry_id,'Solver 索引与固定官方来源')} · ${recordLink('symbol:'+s.public_class,'公开类定义')}</div>`;
}
async function recordPage(id,token){const data=await api('/api/record?id='+enc(id));if(token!==navigation)return;const r=data.record,p=r.payload,solver=r.owner_solver;context(solver);recordBreadcrumb(r);main.innerHTML=head(r.title,r.summary,(solver?catalog.solvers[solver]?.name:'Newton 公共知识')+' / '+(kindNames[r.record_type]||r.record_type))+(solver?solverNavigation(solver,({parameter:'parameters',model_input:'inputs',diagnostic:'diagnostics',paper:'papers',lab_experiment:'experiments'}[r.record_type]||'overview')):'')+`<div class="badges">${badge(r.record_scope)}${badge(r.content_status==='planned'?'待建设':'已发布',r.content_status==='planned'?'proposed':'')}${badge(r.evidence_type,r.evidence_type==='measured'?'measured':'')}${badge('owner: '+(r.owner||r.owner_module))}</div>`;
 if(['parameter','model_input'].includes(r.record_type))main.innerHTML+=`<div class="detail-panel"><h2>声明与默认解析</h2><dl class="kv"><dt>所属位置</dt><dd>${esc(p.owner||r.owner_module)}</dd><dt>声明默认</dt><dd><code>${esc(defaultDisplay(p))}</code></dd><dt>类型 / 单位</dt><dd>${esc(p.type||p.units)}</dd><dt>解析策略</dt><dd>${esc(p.default_policy||p.resolved_default)}</dd></dl><p>${esc(p.documentation||p.description_zh)}</p>${p.experiments?.length?`<div class="actions">${p.experiments.map(e=>{const owner=solver||Object.keys(catalog.solvers).find(s=>catalog.solvers[s].experiments.some(x=>x.id===e));return `<a class="btn" href="#/solvers/${owner}/experiments?case=${enc(e)}">${esc(catalog.solvers[owner]?.name||owner)} 实测：${esc(e)}</a>`;}).join('')}</div>`:'<p>暂无关联的保存实验。</p>'}</div>`;
 main.innerHTML+=`<article class="doc-article">${r.html.replace(/^<h1[^>]*>[\s\S]*?<\/h1>/,'')}</article>`+sourcePanel(r.source_refs)+`<div class="section-head"><h2>一跳证据关系</h2></div><div id="relations"><button id="load-relations">读取关系</button></div>`;
 $('#load-relations').onclick=()=>relations(id);enhance();if(r.record_type==='solver'&&solver){main.innerHTML+=`<div class="actions"><a class="btn primary" href="#/solvers/${solver}">进入 ${esc(catalog.solvers[solver].name)} 专区 →</a></div>`;}
}
function sourcePanel(refs){return refs.length?`<div class="source-summary"><strong>固定源码证据</strong>${refs.map(r=>`<div class="record-source"><a href="#/source/${enc(r.path).replaceAll('%2F','/')}?line=${r.line}">${esc(r.path)}:${r.line}</a> · <a href="${esc(r.url)}" target="_blank" rel="noopener">官方 commit ↗</a><br><span class="muted">SHA256 ${esc(r.sha256)}</span></div>`).join('')}</div>`:'';}
async function relations(id,cursor=''){const target=$('#relations'),data=await api('/api/relations?id='+enc(id)+(cursor?'&cursor='+enc(cursor):''));if(!target?.isConnected)return;const existing=cursor?target.innerHTML.replace(/<button[\s\S]*?<\/button>/g,''):'';const shown=new Set(cursor?[...target.querySelectorAll('[data-rel-id]')].map(e=>e.dataset.relId):[]);target.innerHTML=existing+data.edges.map(e=>{const other=e.source===data.node_id?e.target:e.source;if(shown.has(enc(other)))return '';shown.add(enc(other));const n=data.neighbors.find(n=>n.id===other),call=e.read_next_call||n?.read_next_call;const href=call?.tool==='get_source'?(call.arguments.symbol_id?'#/record/'+enc(other):'#/source/'+enc(call.arguments.path).replaceAll('%2F','/')+'?line='+call.arguments.start_line):'#/record/'+enc(other);return `<a class="related-item" data-rel-id="${enc(other)}" href="${href}">${esc(n?.title||e.related_title||other)}<small>${esc(e.relation)} · ${esc(e.evidence_type||e.evidence||'curated association')}</small></a>`;}).join('')+(data.next_cursor?'<button id="more-relations">继续读取关系</button>':'');if(data.next_cursor)$('#more-relations').onclick=()=>relations(id,data.next_cursor);}
async function documentPage(path,q,token){const d=await api('/api/document?path='+enc(path));if(token!==navigation)return;context(d.solver==='shared'?null:d.solver);main.innerHTML=head(d.title,d.path)+`<div class="actions"><a class="btn" href="/files/${esc(path)}" target="_blank" rel="noopener">原始 Markdown ↗</a>${recordLink(d.record_id,'元数据与关系')}</div><article class="doc-article" style="margin-top:18px">${d.html}</article>`;enhance();const section=q.get('section');if(section){const element=document.getElementById(section)||[...document.querySelectorAll('.doc-article h1,.doc-article h2,.doc-article h3')].find(e=>e.textContent.trim()===section);element?.scrollIntoView();}}
async function sourcePage(path,q,token){const line=Number(q.get('line')||1),r=await api('/api/source?path='+enc(path)+'&line='+line);if(token!==navigation)return;main.innerHTML=head(path,'固定源码文本，逐次核对文件 SHA256。')+`<div class="source-meta">SHA256 ${esc(r.sha256)} · ${r.start}–${r.end} / ${r.total_lines} 行</div><pre class="source-code">${r.lines.map((text,i)=>`<span class="line ${i+r.start===line?'highlight':''}"><span class="ln">${i+r.start}</span><span class="src">${esc(text)}</span></span>`).join('')}</pre><div class="actions"><a class="btn" href="${esc(r.url)}" target="_blank" rel="noopener">官方固定源码 ↗</a>${r.truncated?`<a class="btn" href="#/source/${enc(path).replaceAll('%2F','/')}?line=${r.end+21}">下一段 →</a>`:''}</div>`;}
function enhance(){document.querySelectorAll('.math-block').forEach(e=>{if(window.katex)try{katex.render(e.textContent,e,{displayMode:true,throwOnError:false});}catch{}});if(window.mermaid){mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'neutral'});mermaid.run({querySelector:'.mermaid'}).catch(()=>{});}}
async function searchPage(q,token,cursor='',append=false){if(!append)main.innerHTML=head('全站检索','可按 solver、阶段和知识领域限制范围。检索排名不代表结论可信度。')+`<form id="search-filters" class="filters"><input id="search-text" name="q" aria-label="检索词" value="${esc(q.get('q')||'')}"><select name="solver" aria-label="检索 solver">${[['all','全部 solver 与公共知识'],['shared','仅公共知识'],...Object.entries(catalog.solvers).map(([s,c])=>[s,c.name])].map(([v,l])=>`<option value="${v}" ${q.get('solver')===v?'selected':''}>${esc(l)}</option>`).join('')}</select><select name="stage" aria-label="检索流程阶段"><option value="all">全部阶段</option>${Object.entries(names).map(([s,l])=>`<option value="${s}" ${q.get('stage')===s?'selected':''}>${esc(l)}</option>`).join('')}</select><label><input name="include_shared" type="checkbox" ${q.get('include_shared')==='true'?'checked':''}>包含公共知识</label><button>检索</button></form><div id="search-results"></div>`;
 if(!append)$('#search-filters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('include_shared'))f.set('include_shared','true');location.hash='#/search?'+new URLSearchParams(f);};
 const query=q.get('q');if(!query)return;const params=new URLSearchParams(q);params.set('limit','10');if(cursor)params.set('cursor',cursor);const data=await api('/api/search?'+params);if(token!==navigation)return;const target=$('#search-results');if(append)$('#more-hits')?.remove();target.insertAdjacentHTML('beforeend',data.hits.map(r=>`<a class="search-result" href="${esc(r.route)}">${badge(r.owner_solver||'shared')}${badge(kindNames[r.record_type]||r.record_type)}${r.evidence_type==='proposed'?badge('待验证','proposed'):''}<h3>${esc(r.title)}</h3><p>${esc(r.summary)}</p></a>`).join('')||'<div class="empty">所选范围内未找到匹配记录。</div>');if(data.next_cursor){target.insertAdjacentHTML('beforeend','<button id="more-hits">更多结果</button>');$('#more-hits').onclick=()=>searchPage(q,token,data.next_cursor,true);}}
function legacyRoute(raw){if(raw.startsWith('/'))return null;const [path,query='']=raw.split('?'),[type,...parts]=path.split('/'),name=parts.join('/');let next;
 if(type==='home'||!type)next='/';else if(type==='docs')next='/modules';else if(type==='doc')next='/document/'+name;else if(type==='source')next='/source/'+name;else if(type==='parameter')next='/solvers/vbd/parameters/'+name;else if(type==='model')next='/solvers/vbd/inputs/'+name;
 else if(type==='setting')next='/solvers/shared/parameters/'+(name==='full_surface'?'enable_rigid_soft_full_surface_contact':'substeps');
 else if(type==='solver'){const [s,page,...rest]=parts;const tab={models:'inputs',model:'inputs',parameter:'parameters'}[page]||page;next='/solvers/'+s+(tab?'/'+tab:'')+(rest.length?'/'+rest.join('/'):'');}
 else if(type==='evidence')next=name?'/record/'+name:'/search?q=VBD';else if(type==='search')next='/search';else if(['parameters','experiments','papers','diagnostics'].includes(type))next='/solvers/vbd/'+type;else return null;
 return '#'+next+(query?(next.includes('?')?'&':'?')+query:'');}
async function navigate(){const token=++navigation;const raw=location.hash.slice(1)||'/';const redirected=legacyRoute(raw);if(redirected){history.replaceState(null,'',redirected);return navigate();}const split=raw.indexOf('?'),path=split<0?raw:raw.slice(0,split),q=new URLSearchParams(split<0?'':raw.slice(split+1)),parts=path.split('/').slice(1),type=parts[0]||'home',name=decodeURIComponent(parts.slice(1).join('/'));
 document.body.classList.remove('menu-open');context(type==='solvers'?parts[1]:null);$('#crumb').textContent=({home:'总览',workflow:'仿真流程',modules:'模块与主题',solvers:'Solver 中心',development:'开发测试',agent:'Agent / MCP',search:'检索',document:'知识文档',record:'知识记录',source:'固定源码'}[type]||type);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===type));main.innerHTML='<div class="loading">读取本地知识…</div>';
 try{if(type==='home'){home();developerOverview();}else if(type==='workflow'){if(name)await recordPage('stage:'+name,token);else workflow();}else if(type==='modules')modules();else if(type==='solvers'){if(!parts[1])main.innerHTML=head('Solver 中心','8 个后端分别标记源码索引与深入知识覆盖；各自拥有独立的参数、诊断和实验入口。')+solverCards();else if(parts[3]){const s=catalog.solvers[parts[1]],key=decodeURIComponent(parts.slice(3).join('/'));let r;if(parts[1]==='shared'){r={id:key==='substeps'?'process:substeps':'pipeline:'+key};}else r=(parts[2]==='inputs'?s?.model_inputs:s?.parameters)?.find(p=>(p.name||p.field)===key||p.id===key);if(!r)throw Error('此 solver 中未找到该参数。');await recordPage(r.id,token);}else solverPage(parts[1],parts[2]||'overview',q);}else if(type==='record')await recordPage(name,token);else if(type==='document')await documentPage(name,q,token);else if(type==='source')await sourcePage(name,q,token);else if(type==='search')await searchPage(q,token);else if(type==='development')main.innerHTML=head('开发与测试','固定版本的编码约定、测试入口、安装与迁移知识。')+entryCards(allEntries().filter(e=>['topic:environment','topic:development-testing','topic:migration-integrations'].includes(e.id)));else if(type==='agent')main.innerHTML=head('Agent / MCP 接入','stdio 本地只读服务：检索 → 精确读取 → 关系追溯 → 固定源码。')+`<div class="grid-2"><article class="card"><h3>${docLink('mcp_service/README.md','接入配置与工具说明')}</h3><p>六个工具、固定版本、证据层级与调用示例。</p></article><article class="card"><h3>${docLink('agent/WORKFLOW.md','Agent 调用流程')}</h3><p>参数解释、现象诊断与实验的证据范围。</p></article></div>`;else throw Error('页面不存在。');if(token===navigation&&!q.get('section'))window.scrollTo(0,0);}catch(error){if(token===navigation)main.innerHTML=head('暂时无法读取此内容')+`<div class="notice error">${esc(error.message)}</div><a href="#/">返回 Newton 总览</a>`;}}
$('#global-search').onsubmit=e=>{e.preventDefault();location.hash='#/search?q='+enc($('#query').value);};$('#menu').onclick=()=>document.body.classList.toggle('menu-open');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#query').focus();}});window.addEventListener('hashchange',navigate);
api('/api/catalog').then(data=>{catalog=data;$('#build-id').textContent=catalog.build_id.slice(0,12);navigate();}).catch(error=>{main.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;});
